import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
geom = ee.Geometry.Polygon(
    [[-96.40, 41.20],
     [-96.05, 41.20],
     [-96.05, 41.00],
     [-96.40, 41.00],
     [-96.40, 41.20]]
)

scale = 1000  # per instruction to avoid timeout
maxPixels = 1e9

def gsw_march_metrics(year, label):
    start = ee.Date.fromYMD(year, 3, 1)
    end = start.advance(1, 'month')
    col = (ee.ImageCollection('JRC/GSW1_4/MonthlyHistory')
           .filterBounds(geom)
           .filterDate(start, end))
    n = col.size().getInfo()
    if n == 0:
        return {'label': label, 'images': n, 'status': 'C1', 'msg': 'No GSW monthly image.'}

    img = col.first().select('water')
    # Observation mask: >0 means valid observation (not NoData)
    obs_mask = img.gt(0)
    obs_px = img.updateMask(obs_mask).reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=maxPixels
    ).get('water').getInfo()
    if obs_px is None or obs_px == 0:
        return {'label': label, 'images': n, 'status': 'C2', 'msg': 'No valid observed pixels.'}

    # Water = value == 2
    water_mask = img.eq(2)
    water_px = img.updateMask(water_mask).reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=maxPixels
    ).get('water').getInfo()
    water_area_m2 = ee.Image.pixelArea().updateMask(water_mask).reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=scale, maxPixels=maxPixels
    ).get('area').getInfo()

    if water_area_m2 is None or not math.isfinite(water_area_m2) or water_area_m2 < 0:
        return {'label': label, 'images': n, 'status': 'C3', 'msg': 'Invalid water area.'}

    return {
        'label': label, 'images': n, 'status': 'OK',
        'obs_px': int(obs_px),
        'water_px': int(water_px) if water_px is not None else 0,
        'water_km2': float(water_area_m2) / 1e6
    }

try:
    r2018 = gsw_march_metrics(2018, '2018-03')
    r2019 = gsw_march_metrics(2019, '2019-03')

    print(f"2018-03 Images: {r2018.get('images')}")
    print(f"2019-03 Images: {r2019.get('images')}")

    # Handle non-OK statuses with precedence C1 > C2 > C3 > D
    if r2018.get('status') != 'OK' or r2019.get('status') != 'OK':
        for r in [r2018, r2019]:
            if r.get('status') != 'OK':
                print(f"{r['label']} Status: {r['status']} ({r.get('msg','')})")
        statuses = [r2018.get('status'), r2019.get('status')]
        if 'C1' in statuses:
            print("C1"); sys.exit(0)
        elif 'C2' in statuses:
            print("C2"); sys.exit(0)
        elif 'C3' in statuses:
            print("C3"); sys.exit(0)
        else:
            print("D"); sys.exit(0)

    print(f"2018 Obs px: {r2018['obs_px']}, Water px: {r2018['water_px']}, Water km²: {r2018['water_km2']:.2f}")
    print(f"2019 Obs px: {r2019['obs_px']}, Water px: {r2019['water_px']}, Water km²: {r2019['water_km2']:.2f}")

    # Validate results
    if (r2018['water_km2'] is None) or (r2019['water_km2'] is None):
        print("C3"); sys.exit(0)
    if not (math.isfinite(r2018['water_km2']) and math.isfinite(r2019['water_km2'])):
        print("C3"); sys.exit(0)

    diff = r2019['water_km2'] - r2018['water_km2']
    ratio = (r2019['water_km2'] / r2018['water_km2']) if r2018['water_km2'] > 0 else float('inf')
    ratio_str = f"{ratio:.2f}" if math.isfinite(ratio) else "inf"
    print(f"Δ Water km² (2019-2018): {diff:.2f}, Ratio: {ratio_str}")

    if diff > 0:
        print("A")
    else:
        print("B")

except ee.EEException as e:
    print(f"GEE Error: {str(e)[:200]}")
    print("D")
except Exception as e:
    print(f"Error: {str(e)[:200]}")
    print("D")
